--
-- Name: agency_offenses_view; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE agency_offenses_view (
    id integer NOT NULL,
    year smallint NOT NULL,
    agency_id bigint NOT NULL,
    offense_id integer,
    offense_code character varying(20),
    offense_name text,
    reported integer,
    unfounded integer,
    actual integer,
    cleared integer,
    juvenile_cleared integer,
    ori text,
    pub_agency_name text,
    state_postal_abbr character varying(2)
);


