--
-- Name: participation_rates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE participation_rates (
    participation_id integer NOT NULL,
    year smallint NOT NULL,
    state_id bigint,
    state_name character varying(255),
    county_id bigint,
    county_name character varying(255),
    total_agencies integer,
    participating_agencies integer,
    participation_rate double precision,
    nibrs_participating_agencies integer,
    nibrs_participation_rate double precision,
    covered_agencies integer,
    covered_rate double precision,
    total_population bigint,
    participating_population bigint
);


--
-- Name: pe_employee_data; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE pe_employee_data (
    agency_id bigint NOT NULL,
    data_year smallint NOT NULL,
    reported_flag character(1) NOT NULL,
    male_officer bigint,
    male_civilian bigint,
    male_total bigint,
    female_officer bigint,
    female_civilian bigint,
    female_total bigint,
    officer_rate bigint,
    employee_rate bigint,
    data_home character(1),
    ddocname character varying(100),
    did bigint,
    ff_line_number bigint,
    orig_format character(1),
    pe_employee_id bigint NOT NULL
);


--
-- Name: pe_patrol; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE pe_patrol (
    agency_id bigint NOT NULL,
    data_year smallint NOT NULL,
    patrol_shift_id smallint NOT NULL,
    patrol_type_id smallint NOT NULL,
    patrol_count integer,
    pe_employee_id bigint NOT NULL
);


--
-- Name: pe_patrol_shift; Type: TABLE; Schema: public; Owner: -
--

